/** K线数据 */
interface KLineData {
  /** 时间戳 */
  timestamp: number;
  /** 开盘价 */
  open: number;
  /** 最高价 */
  high: number;
  /** 最低价 */
  low: number;
  /** 收盘价 */
  close: number;
  /** 成交量（可选） */
  volume?: number;
  /** 成交额（可选） */
  turnover?: number;
  /** 持仓量（可选） */
  openInterest?: number;
  /** 其他自定义字段 */
  [key: string]: any;
}

/** 图形配置 */
interface IndicatorFigure {
  /** 数据键名 */
  key: string;
  /** 提示标题（可选） */
  title?: string;
  /** 图形类型（可选） */
  type?: string;
  /** 基准值（可选） */
  baseValue?: number;
}

/** 指标样式 */
interface IndicatorStyle {
  /** OHLC颜色 */
  ohlc: { upColor: string; downColor: string; noChangeColor: string };
  /** 柱状图样式 */
  bars: any[];
  /** 线条样式 */
  lines: any[];
  /** 圆形样式 */
  circles: any[];
}

/** 可见范围 */
interface VisibleRange {
  from: number;
  to: number;
  realFrom: number;
  realTo: number;
}

/** 边界信息 */
interface Bounding {
  width: number;
  height: number;
  left: number;
  right: number;
  top: number;
  bottom: number;
}

/** K线空间 */
interface BarSpace {
  bar: number;
  halfBar: number;
  gapBar: number;
  halfGapBar: number;
}

/** X轴/Y轴 */
interface Axis {
  /** 值转像素 */
  convertToPixel: (value: number) => number;
  /** 像素转值（可选） */
  convertFromPixel?: (pixel: number) => number;
}

/** 绘制参数 */
interface IndicatorDrawParams {
  /** Canvas 2D上下文 */
  ctx: CanvasRenderingContext2D;
  /** K线数据列表 */
  kLineDataList: KLineData[];
  /** 指标对象 */
  indicator: Indicator;
  /** 可见范围 */
  visibleRange: VisibleRange;
  /** 边界信息 */
  bounding: Bounding;
  /** K线空间 */
  barSpace: BarSpace;
  /** 默认样式 */
  defaultStyles: IndicatorStyle;
  /** X轴 */
  xAxis: Axis;
  /** Y轴 */
  yAxis: Axis;
}

/** 指标对象 */
interface Indicator {
  /** 指标名称 */
  name: string;
  /** 简称 */
  shortName: string;
  /** 精度 */
  precision: number;
  /** 计算参数 */
  calcParams: any[];
  /** 图形配置 */
  figures: IndicatorFigure[];
  /** 计算结果 */
  result: any[];
  /** 样式（可选） */
  styles?: Partial<IndicatorStyle>;
  /**
   * 计算函数
   * @param dataList K线数据数组
   * @param indicator 指标对象
   */
  calc: (dataList: KLineData[], indicator: Indicator) => any[];
  /**
   * 重新生成图形配置（可选）
   * @param calcParams 计算参数
   */
  regenerateFigures?: (calcParams: any[]) => IndicatorFigure[];
  /**
   * 自定义绘制函数（可选）
   * @param params 绘制参数
   * @returns 是否跳过默认绘制
   */
  draw?: (params: IndicatorDrawParams) => boolean;
}

/** 指标模板 */
interface IndicatorTemplate {
  /** 指标名称 */
  name: string;
  /** 简称 */
  shortName: string;
  /** 精度（可选） */
  precision?: number;
  /** 计算参数（可选） */
  calcParams?: any[];
  /** 图形配置（可选） */
  figures?: IndicatorFigure[];
  /** 计算函数 */
  calc: (dataList: KLineData[], indicator: Indicator) => any[];
  /** 重新生成图形配置（可选） */
  regenerateFigures?: (calcParams: any[]) => IndicatorFigure[];
  /** 绘制函数（可选） */
  draw?: (params: IndicatorDrawParams) => boolean;
}

/** 全局变量声明 - 在 calc 函数中可直接使用 */
declare const dataList: KLineData[];
declare const indicator: Indicator;
declare const kLineData: KLineData;
declare const calcParams: any[];
declare const figures: IndicatorFigure[];
declare const result: Record<string, any>;
declare const i: number;
